function payoff(balance, apr, minPct, minFixed){
  balance=+balance; apr=+apr; minPct=(+minPct); if(isNaN(minPct))minPct=0.02;
  minFixed=(+minFixed)||0;
  if(!(balance>0)) return {error:'账单余额须为正数'};
  if(!(apr>=0)) return {error:'年利率须非负'};
  var r=apr/12;
  var bal=balance, months=0, totalInterest=0;
  var cap=1200;
  while(bal>0.005 && months<cap){
    var interest=bal*r;
    var pay=Math.max(minPct*bal, minFixed);
    if(pay<=interest+0.005){ return {months:-1, note:'最低还款 ≤ 当月利息，永远无法还清（请提高每月还款额）', totalInterest:0, totalPaid:0, monthly:pay}; }
    pay=Math.min(pay, bal+interest);
    bal=bal+interest-pay;
    totalInterest+=interest; months++;
  }
  var totalPaid=balance+totalInterest;
  return {months:months, totalInterest:Math.round(totalInterest*100)/100, totalPaid:Math.round(totalPaid*100)/100, monthly:Math.max(minPct*balance,minFixed), note:''};
}
var EXPORTS={payoff:payoff};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CreditCardPayoffForgePure = EXPORTS; }
